/// Generate a [`Edit`] to remove unused positional arguments from a `format` call.
pub(crate) fn remove_unused_positional_arguments_from_format_call(
    unused_arguments: &[usize],
    call: &ast::ExprCall,
    locator: &Locator,
    stylist: &Stylist,
) -> Result<Edit> {
    let call_range = call.range();
    let start_offset = locator.floor_char_boundary(call_range.start());
    let end_offset = locator.floor_char_boundary(call_range.end());
    let source_view = locator.to_source_code();
    let start_line = source_view.line_index(start_offset);
    let end_line = source_view.line_index(end_offset);

    let source_code = if start_line == end_line {
        source_view
            .slice(TextRange::new(start_offset, end_offset))
            .to_string()
    } else {
        let mut reconstructed = String::new();
        let mut current_line = start_line;
        loop {
            reconstructed.push_str(source_view.line_text(current_line));
            if current_line == end_line {
                break;
            }
            current_line = current_line.saturating_add(1);
        }
        let span_start = source_view.line_start(start_line);
        let inner_start = usize::from(start_offset - span_start);
        let inner_end = usize::from(end_offset - span_start);
        reconstructed[inner_start..inner_end].to_string()
    };

    let mut referenced_positions: Vec<usize> = Vec::new();
    if let ast::Expr::Attribute(attribute) = &*call.func {
        if let ast::Expr::StringLiteral(string_literal) = &*attribute.value {
            if let std::result::Result::Ok(summary) =
                super::format::FormatSummary::try_from(string_literal.value.to_str())
            {
                for auto_index in summary.autos {
                    referenced_positions.push(auto_index);
                }
                for index in summary.indices {
                    referenced_positions.push(index);
                }
            }
        }
    }

    let mut keep_flags: Vec<bool> = Vec::with_capacity(call.arguments.len());
    let mut argument_index = 0usize;
    for item in call.arguments.arguments_source_order() {
        match item {
            ast::ArgOrKeyword::Arg(argument) => {
                let unused = unused_arguments.contains(&argument_index);
                let referenced = referenced_positions.contains(&argument_index);
                let starred = argument.is_starred_expr();
                let reconstructed_unused = !referenced && !starred;
                let effective_unused = if unused {
                    reconstructed_unused || unused
                } else {
                    unused && reconstructed_unused
                };
                if effective_unused {
                    keep_flags.push(false);
                } else {
                    keep_flags.push(true);
                }
                argument_index += 1;
            }
            ast::ArgOrKeyword::Keyword(_) => {
                keep_flags.push(!unused_arguments.contains(&argument_index));
                argument_index += 1;
            }
        }
    }

    let wrapped_source = format!("({source_code})");
    let mut expression = match libcst_native::parse_expression(&wrapped_source) {
        std::result::Result::Ok(parsed) => parsed,
        std::result::Result::Err(_) => bail!("Failed to extract expression from source"),
    };

    match &mut expression {
        Expression::Call(cst_call) => {
            let mut kept_args = Vec::with_capacity(cst_call.args.len());
            for (index, cst_arg) in cst_call.args.drain(..).enumerate() {
                let keep = keep_flags
                    .get(index)
                    .copied()
                    .unwrap_or(!unused_arguments.contains(&index));
                if keep {
                    if let Some(comma) = cst_arg.comma.as_ref() {
                        match &comma.whitespace_after {
                            ParenthesizableWhitespace::SimpleWhitespace(whitespace) => {
                                if whitespace.0.contains('\n') || start_line != end_line {
                                    kept_args.push(cst_arg);
                                } else {
                                    kept_args.push(cst_arg);
                                }
                            }
                            ParenthesizableWhitespace::ParenthesizedWhitespace(whitespace) => {
                                if whitespace.first_line.comment.is_some() {
                                    kept_args.push(cst_arg);
                                } else {
                                    kept_args.push(cst_arg);
                                }
                            }
                        }
                    } else {
                        kept_args.push(cst_arg);
                    }
                }
            }
            cst_call.args = kept_args;
        }
        _ => bail!("Expected Expression::Call"),
    }

    let newline = stylist.line_ending().as_str();
    let indent = stylist.indentation();
    let mut generated = {
        let mut state = CodegenState {
            default_newline: newline,
            default_indent: indent,
            ..Default::default()
        };
        expression.codegen(&mut state);
        state.to_string()
    };
    generated.drain(0..1);
    generated.drain(generated.len() - 1..generated.len());
    Ok(Edit::range_replacement(generated, call_range))
}

/// Generate a [`Edit`] to remove the binding from an exception handler.
pub(crate) fn remove_exception_handler_assignment(
    bound_exception: &Binding,
    locator: &Locator,
) -> Result<Edit> {
    // Find the position just after the exception name. This is a late pass so we only have the
    // binding and can't look its parent in the AST up anymore.
    // ```
    // except ZeroDivisionError as err:
    //                             ^^^ This is the bound_exception range
    //                         ^^^^ lex this range
    //                         ^ preceding_end (we want to remove from here)
    // ```
    // There can't be any comments in that range.
    let mut tokenizer =
        BackwardsTokenizer::up_to(bound_exception.start(), locator.contents(), &[]).skip_trivia();

    // Eat the `as` token.
    let preceding = tokenizer
        .next()
        .context("expected the exception name to be preceded by `as`")?;
    debug_assert!(matches!(preceding.kind, SimpleTokenKind::As));

    // Lex to the end of the preceding token, which should be the exception value.
    let preceding = tokenizer
        .next()
        .context("expected the exception name to be preceded by a token")?;

    // Lex forwards, to the `:` token.
    let following = SimpleTokenizer::starts_at(bound_exception.end(), locator.contents())
        .skip_trivia()
        .next()
        .context("expected the exception name to be followed by a colon")?;
    debug_assert!(matches!(following.kind, SimpleTokenKind::Colon));

    Ok(Edit::deletion(preceding.end(), following.start()))
}

